//! SentryNet alert notification module.
//!
//! Provides desktop notification delivery for alerts generated by the scanner.
//! Notifications are only sent when the `enable_notifications` config flag is true.
//!
//! Alert types and their notification titles:
//!
//! | alert_type      | title template                              |
//! |-----------------|---------------------------------------------|
//! | new_device      | "New device discovered"                     |
//! | new_port        | "New port opened"                           |
//! | device_offline  | "Device offline"                            |
//! | port_closed     | "Port closed"                               |

use crate::database::Alert;
use tauri::Manager;
use tauri_plugin_notification::NotificationExt;

// ──────────────────────────────────────────────
// Notification helpers
// ──────────────────────────────────────────────

/// Map an alert type to a human-readable title for the notification.
pub fn alert_title(alert_type: &str) -> &'static str {
    match alert_type {
        "new_device" => "New device discovered",
        "new_port" => "New port opened",
        "device_offline" => "Device offline",
        "port_closed" => "Port closed",
        _ => "SentryNet alert",
    }
}

/// Send a desktop notification for a single alert.
///
/// Uses the Tauri notification plugin. Errors are logged but do not
/// propagate — a single notification failure must not break the scan flow.
fn send_notification(window: &tauri::WebviewWindow, alert: &Alert) {
    let title = alert_title(&alert.alert_type);
    let app_handle = window.app_handle();
    match app_handle
        .notification()
        .builder()
        .title(title)
        .body(&alert.message)
        .show()
    {
        Ok(_) => {
            eprintln!(
                "[sentrynet] notification sent: {} for {}",
                alert.alert_type,
                alert.device_ip
            );
        }
        Err(e) => {
            eprintln!(
                "[sentrynet] failed to send notification for alert {}: {e}",
                alert.id.unwrap_or(0)
            );
        }
    }
}

// ──────────────────────────────────────────────
// Public API
// ──────────────────────────────────────────────

/// Send desktop notifications for a list of alerts.
///
/// Iterates over `alerts` and sends a notification for each one.
/// Errors from individual notifications are logged but do not stop the loop.
pub fn send_alert_notifications(window: &tauri::WebviewWindow, alerts: &[Alert]) {
    if alerts.is_empty() {
        return;
    }
    for alert in alerts {
        send_notification(window, alert);
    }
}

/// Send a desktop notification for a single alert.
///
/// Convenience wrapper for callers that have one alert to notify about.
pub fn send_single_notification(window: &tauri::WebviewWindow, alert: &Alert) {
    send_notification(window, alert);
}

/// Check whether notifications are enabled for the given app handle.
///
/// Reads the `enable_notifications` config value from the database.
/// Returns `true` if notifications should be sent.
pub fn notifications_enabled(app: &tauri::AppHandle) -> bool {
    let db_path = match app.try_state::<crate::api::ApiServerState>() {
        Some(state) => state.info.db_path.clone(),
        None => return false,
    };
    match crate::database::Database::open(&db_path) {
        Ok(db) => {
            let config = crate::api::read_config_from_db(&db);
            config.enable_notifications
        }
        Err(_) => false,
    }
}

// ──────────────────────────────────────────────
// Tests
// ──────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_alert_title_mapping() {
        assert_eq!(alert_title("new_device"), "New device discovered");
        assert_eq!(alert_title("new_port"), "New port opened");
        assert_eq!(alert_title("device_offline"), "Device offline");
        assert_eq!(alert_title("port_closed"), "Port closed");
        assert_eq!(alert_title("unknown_type"), "SentryNet alert");
    }

    #[test]
    fn test_send_alert_notifications_empty() {
        // Should not panic or error with an empty list.
        let alerts: Vec<Alert> = vec![];
        // We can't easily test the actual notification without a window,
        // but we verify the function exists and accepts the right types.
        let _ = &send_alert_notifications;
        let _ = &alerts;
    }

    #[test]
    fn test_notifications_enabled_default() {
        // Create a test database with default config (notifications enabled)
        let db = crate::database::Database::open_memory().unwrap();
        let config = crate::api::read_config_from_db(&db);
        assert!(config.enable_notifications);
    }

    #[test]
    fn test_notifications_enabled_disabled() {
        // Create a test database with notifications disabled
        let db = crate::database::Database::open_memory().unwrap();
        crate::api::write_config_to_db(
            &db,
            &crate::api::AppConfig {
                enable_notifications: false,
                ..crate::api::AppConfig::default()
            },
        )
        .unwrap();
        let config = crate::api::read_config_from_db(&db);
        assert!(!config.enable_notifications);
    }

    #[test]
    fn test_alert_title_all_types() {
        // Verify all known alert types have proper titles
        let types = vec![
            "new_device",
            "new_port",
            "device_offline",
            "port_closed",
        ];
        for alert_type in types {
            let title = alert_title(alert_type);
            assert!(!title.is_empty(), "title for {alert_type} should not be empty");
            assert!(
                title.len() > 3,
                "title for {alert_type} should be descriptive"
            );
        }
    }

    #[test]
    fn test_alert_struct_serialization() {
        let alert = Alert {
            id: Some(1),
            device_ip: "192.168.1.100".to_string(),
            alert_type: "new_device".to_string(),
            message: "New device discovered: 192.168.1.100".to_string(),
            acknowledged: false,
            created_at: chrono::Utc::now(),
        };
        let json = serde_json::to_string(&alert).unwrap();
        assert!(json.contains("\"device_ip\":\"192.168.1.100\""));
        assert!(json.contains("\"alert_type\":\"new_device\""));
        assert!(json.contains("\"acknowledged\":false"));
    }
}
